  private static void showMessage(final String title, final int option, final int width, final String... messages) {
    final StringBuilder messagesBuilder = new StringBuilder();
    for (String message : messages) {
      messagesBuilder.append(String.format("<p style='width: %dpx'>%s</p>", width, alefj2cl.BrowserHelpers.escapeHtml(message)));
    }
    SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(null, title + "\n" + String.join("\n", messages)));

  }

